using Nethereum.ABI.FunctionEncoding.Attributes;
using Nethereum.Contracts;
using Nethereum.Hex.HexConvertors.Extensions;

namespace Nethereum.X402.IntegrationTests.Helpers;

public static class SettlementContracts
{
    public const string BatcherAddress = "0x00000000000000000000000000000000000B4701";

    public static readonly byte[] Batcher = "".HexToByteArray();

    public static readonly byte[] SettlingProxy = "".HexToByteArray();

    [Function("batch")]
    public class BatchFunction : FunctionMessage
    {
        [Parameter("address", "target", 1)]
        public string Target { get; set; } = string.Empty;

        [Parameter("bytes", "a", 2)]
        public byte[] First { get; set; } = Array.Empty<byte>();

        [Parameter("bytes", "b", 3)]
        public byte[] Second { get; set; } = Array.Empty<byte>();
    }

    [Function("setFailNext")]
    public class SetFailNextFunction : FunctionMessage
    {
        [Parameter("bool", "value", 1)]
        public bool Value { get; set; }
    }

    [Function("transferFrom", "bool")]
    public class TransferFromFunction : FunctionMessage
    {
        [Parameter("address", "from", 1)]
        public string From { get; set; } = string.Empty;

        [Parameter("address", "to", 2)]
        public string To { get; set; } = string.Empty;

        [Parameter("uint256", "value", 3)]
        public System.Numerics.BigInteger Value { get; set; }
    }
}
